#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: poh-guardian — шаги владельца (≈5 минут). Запуск: bash wizard/setup-owner.sh
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=3
cd "$(dirname "$0")/.."
mkdir -p "$HOME/.config/poh-guardian"
ENV_FILE="$HOME/.config/poh-guardian/guardian.env"   # для разбора на Mac, когда Actions недоступен (600)
# прежнее имя файла (до перехода на GLM) — переносим, чтобы визард помнил введённое
[[ -f "$HOME/.config/poh-guardian/telegram.env" && ! -f "$ENV_FILE" ]] && mv "$HOME/.config/poh-guardian/telegram.env" "$ENV_FILE"
touch "$ENV_FILE"; chmod 600 "$ENV_FILE"

banner "Хранитель сервера: Telegram-бот и ключ Z.AI (GLM)"

# ── 1. Telegram-бот ───────────────────────────────────────────────────────
stage "Telegram: отдельный бот хранителя"
say "Хранитель пишет сюда «🚨 сбой — разбираюсь», доклад и кнопки ✅/❌."
open_url "https://t.me/BotFather"
step "В BotFather: /newbot → имя (напр. «Хранитель dede») → username, оканчивающийся на bot."
step "BotFather пришлёт токен вида 123456:ABC… — скопируйте его."
ask_secret TELEGRAM_BOT_TOKEN "Вставьте токен бота (ввод скрыт):"
me=$(curl -s -m 15 "https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/getMe" || true)
bot=$(printf '%s' "$me" | python3 -c 'import json,sys; d=json.load(sys.stdin); print(d["result"]["username"] if d.get("ok") else "")' 2>/dev/null || true)
[[ -n "$bot" ]] || { warn "Telegram не узнал токен — перезапустите визард и вставьте токен ещё раз."; exit 1; }
say "Бот @$bot найден."
open_url "https://t.me/$bot"
step "Нажмите «Старт» (или отправьте боту любое сообщение) — так бот узнает ваш чат."
pause "Отправили? Enter"
TELEGRAM_CHAT_ID=$(curl -s -m 15 "https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/getUpdates" | python3 -c '
import json,sys
d=json.load(sys.stdin); ids=[u["message"]["chat"]["id"] for u in d.get("result",[]) if "message" in u and u["message"]["chat"]["type"]=="private"]
print(ids[-1] if ids else "")' 2>/dev/null || true)
[[ -n "$TELEGRAM_CHAT_ID" ]] || ask TELEGRAM_CHAT_ID "Не нашёл ваш чат — напишите боту ещё раз и введите chat id вручную (или Enter после повтора):"
write_env TELEGRAM_BOT_TOKEN "$TELEGRAM_BOT_TOKEN"
write_env TELEGRAM_CHAT_ID "$TELEGRAM_CHAT_ID"
chmod 600 "$ENV_FILE"
set_secret TELEGRAM_BOT_TOKEN "$TELEGRAM_BOT_TOKEN"
set_secret TELEGRAM_CHAT_ID "$TELEGRAM_CHAT_ID"
TELEGRAM_BOT_TOKEN="$TELEGRAM_BOT_TOKEN" TELEGRAM_CHAT_ID="$TELEGRAM_CHAT_ID" \
  python3 agent/telegram.py send "🫡 Хранитель подключён. Сюда придут сбои, доклады и кнопки ✅/❌." >/dev/null
say "Проверьте Telegram: должно прийти «🫡 Хранитель подключён»."
pause

# ── 2. Ключ Z.AI (GLM) для агента ─────────────────────────────────────────
stage "Z.AI: ключ GLM для агента-хранителя"
say "Хранитель думает на GLM (Z.AI Coding Plan) — ваша подписка Claude не используется."
say "Можно взять существующий ключ Coding Plan или создать отдельный «guardian» (так его проще отозвать)."
open_url "https://z.ai/manage-apikey/apikey-list"
step "API Keys → Create a new API key (имя: guardian) → скопируйте ключ."
ask_secret ZAI_API_KEY "Вставьте ключ Z.AI (ввод скрыт):"
code=$(curl -s -m 60 -o /dev/null -w '%{http_code}' https://api.z.ai/api/anthropic/v1/messages \
  -H "x-api-key: $ZAI_API_KEY" -H "anthropic-version: 2023-06-01" -H "content-type: application/json" \
  -d '{"model":"glm-5.3","max_tokens":8,"messages":[{"role":"user","content":"ping"}]}' || true)
if [[ "$code" == 200 ]]; then say "Ключ работает (Z.AI ответил 200)."
else warn "Z.AI ответил $code — проверьте ключ и пакет Coding Plan; можно продолжить и поправить позже."; fi
write_env ZAI_API_KEY "$ZAI_API_KEY"   # для разбора на Mac, когда Actions недоступен
chmod 600 "$ENV_FILE"
set_secret ZAI_API_KEY "$ZAI_API_KEY"
pause

# ── 3. Учения ─────────────────────────────────────────────────────────────
stage "Учения: агент поднимает канарейку"
say "Остановим тестовый сервис-канарейку на сервере и разбудим агента в GitHub Actions."
say "Через 2–4 минуты в Telegram: «🧪 Учения…», затем доклад «канарейка поднята»."
if confirm "Запустить учения?"; then
  ssh harness-mts 'systemctl --user stop poh-guardian-canary' || warn "не смог остановить канарейку по SSH"
  gh workflow run heal.yml -f scenario=canary -f reason="учения из визарда" \
    && { sleep 8; gh run watch "$(gh run list --workflow heal.yml -L 1 --json databaseId -q '.[0].databaseId')" || true; } \
    || SKIPPED+=("учения: gh workflow run heal.yml -f scenario=canary")
else
  SKIPPED+=("учения: gh workflow run heal.yml -f scenario=canary (после ssh harness-mts 'systemctl --user stop poh-guardian-canary')")
fi

finish
